            packages.append((name, deps))
            idx += 1

        # Build graph and in_degree
        for name, deps in packages:
            name_to_idx[name] = len(name_to_idx)
            idx_map[len(idx_map)] = name
            for dep in deps:
                graph[dep].append(name)
                in_degree[name] += 1
            if name not in in_degree:
                in_degree[name] = 0

        # Initialize queue with nodes having zero in-degree
        queue = deque()
        for name in names:
            if in_degree[name] == 0:
                queue.append(name)

        topo_order = []
        while queue:
            if len(queue) > 1:
                # To get lex smallest, always pick the smallest available
                queue = deque(sorted(queue))
            current = queue.popleft()
            topo_order.append(current)
            for neighbor in graph[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(topo_order) == len(names):
            for name in topo_order:
                print(name)
        else:
            print("cannot be ordered")
        print()  # blank line between test cases

